WITH positive_conversations AS (SELECT COUNT(subq_3.positive_conversations_measure) AS positive_conversations, subq_3.month AS month, dim_agent.agent_type AS agent_type, dim_user.is_premium AS is_premium FROM (SELECT CASE WHEN csat_score >= 3 THEN ticket_id END AS positive_conversations_measure, dateTrunc('month', raised_at) AS month, final_agent_id AS agent, user_id AS user, final_agent_id AS agent, user_id AS user FROM fact_ticket_journey WHERE 1 = 1) AS subq_3 JOIN dim_agent AS dim_agent ON subq_3.agent = dim_agent.agent_id JOIN dim_user AS dim_user ON subq_3.user = dim_user.user_id GROUP BY month, is_premium, agent_type), num_tickets_raised AS (SELECT COUNT(subq_1.num_tickets_raised_measure) AS num_tickets_raised, subq_1.month AS month, dim_agent.agent_type AS agent_type, dim_user.is_premium AS is_premium FROM (SELECT ticket_id AS num_tickets_raised_measure, dateTrunc('month', raised_at) AS month, final_agent_id AS agent, user_id AS user, final_agent_id AS agent, user_id AS user FROM fact_ticket_journey WHERE 1 = 1) AS subq_1 JOIN dim_agent AS dim_agent ON subq_1.agent = dim_agent.agent_id JOIN dim_user AS dim_user ON subq_1.user = dim_user.user_id GROUP BY month, is_premium, agent_type), prefinal_cte AS (SELECT positive_conversations.agent_type AS agent_type, positive_conversations.is_premium AS is_premium, positive_conversations.month AS month, MAX(positive_conversations.positive_conversations) AS positive_conversations, MAX(num_tickets_raised.num_tickets_raised) AS num_tickets_raised FROM positive_conversations JOIN num_tickets_raised AS num_tickets_raised ON positive_conversations.agent_type = num_tickets_raised.agent_type AND positive_conversations.is_premium = num_tickets_raised.is_premium AND positive_conversations.month = num_tickets_raised.month GROUP BY agent_type, is_premium, month) SELECT is_premium AS is_premium, month AS month, agent_type AS agent_type, MAX(positive_conversations / num_tickets_raised) AS CSAT_SCORE FROM prefinal_cte GROUP BY is_premium, month, agent_type